@androidx.media3.common.util.UnstableApi
public class MainActivity extends Activity {
 private final Handler h=new Handler(Looper.getMainLooper());
 private final ExecutorService io=Executors.newSingleThreadExecutor();
 private ListenableFuture<MediaController> pending; private MediaController ctl;
 private List<Store.Song> songs=new ArrayList<>();
 private LinearLayout root,body,list; private TextView title,artist,time,play,heart,shuffle,repeat,status; private SeekBar seek;
 private String page="首頁",filter=""; private boolean dragging=false,scanning=false,dead=false,initial=true;
 private int bg,panel,fg,muted,gold;
 private final Runnable tick=new Runnable(){public void run(){if(!dead){refresh();h.postDelayed(this,500);}}};
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);getWindow().getDecorView().setSystemUiVisibility(5894);
 songs=Store.read(this,"library");theme();render();
 SessionToken token=new SessionToken(this,new ComponentName(this,PlaybackService.class));
 pending=new MediaController.Builder(this,token).buildAsync();pending.addListener(()->{if(dead)return;try{ctl=pending.get();ctl.addListener(new Player.Listener(){@Override public void onEvents(Player p,Player.Events e){refresh();}@Override public void onPlayerError(PlaybackException ex){if(status!=null)status.setText("無法播放，請重新掃描或選下一首");}});restore();refresh();}catch(Exception e){if(status!=null)status.setText("播放服務連線失敗");}},command->h.post(command));h.post(tick);
 if(hasAudio()||!Store.prefs(this).getStringSet("trees",Collections.emptySet()).isEmpty())scan(false);}
 private boolean hasAudio(){return checkSelfPermission(Build.VERSION.SDK_INT>=33?"android.permission.READ_MEDIA_AUDIO":Manifest.permission.READ_EXTERNAL_STORAGE)==PackageManager.PERMISSION_GRANTED;}
 private void permission(){if(hasAudio())scan(true);else requestPermissions(new String[]{Build.VERSION.SDK_INT>=33?"android.permission.READ_MEDIA_AUDIO":Manifest.permission.READ_EXTERNAL_STORAGE},71);}
 @Override public void onRequestPermissionsResult(int req,String[] perms,int[] result){super.onRequestPermissionsResult(req,perms,result);if(req==71&&result.length>0&&result[0]==PackageManager.PERMISSION_GRANTED)scan(true);}
 private void restore(){if(ctl==null||!initial)return;initial=false;if(ctl.getMediaItemCount()>0)return;List<Store.Song> q=Store.read(this,"queue");if(q.isEmpty())q=new ArrayList<>(songs);if(q.isEmpty())return;String last=Store.prefs(this).getString("last","");long pos=Store.prefs(this).getLong("pos",0);int i=0;for(int j=0;j<q.size();j++)if(q.get(j).uri.equals(last)){i=j;break;}setQueue(q,i,pos,Store.prefs(this).getBoolean("auto",true));}
 private void setQueue(List<Store.Song> q,int idx,long pos,boolean start){if(ctl==null||q.isEmpty())return;List<MediaItem> items=new ArrayList<>();for(Store.Song s:q)items.add(s.item());ctl.setMediaItems(items,Math.max(0,Math.min(idx,items.size()-1)),Math.max(0,pos));ctl.setShuffleModeEnabled(Store.prefs(this).getBoolean("shuffle",false));ctl.setRepeatMode(Store.prefs(this).getInt("repeat",Player.REPEAT_MODE_ALL));ctl.prepare();if(start)ctl.play();else ctl.pause();refresh();}
 private void playToggle(){if(ctl==null)return;if(ctl.getMediaItemCount()==0){if(!songs.isEmpty())setQueue(songs,0,0,true);else permission();return;}if(ctl.getPlayWhenReady())ctl.pause();else{if(ctl.getPlaybackState()==Player.STATE_IDLE)ctl.prepare();if(ctl.getPlaybackState()==Player.STATE_ENDED)ctl.seekToDefaultPosition();ctl.play();}refresh();}
 private void scan(boolean user){if(scanning)return;scanning=true;if(status!=null)status.setText("正在掃描音樂…");io.execute(()->{LinkedHashMap<String,Store.Song> map=new LinkedHashMap<>();String err="";try{if(hasAudio()){Uri base=MediaStore.Audio.Media.EXTERNAL_CONTENT_URI;String[] cols={"_id","title","artist","album"};try(Cursor c=getContentResolver().query(base,cols,null,null,"title COLLATE NOCASE")){if(c!=null)while(c.moveToNext()){String id=ContentUris.withAppendedId(base,c.getLong(0)).toString();map.put(id,new Store.Song(id,nonempty(c.getString(1),"未命名歌曲"),nonempty(c.getString(2),"未知演出者"),nonempty(c.getString(3),"")));}}}for(String t:Store.prefs(this).getStringSet("trees",Collections.emptySet())){try{Uri tree=Uri.parse(t);walk(tree,DocumentsContract.getTreeDocumentId(tree),map,0,new HashSet<>());}catch(Exception e){err="部分資料夾無法讀取";}}}catch(Exception e){err="部分音樂無法讀取";}final String error=err;final List<Store.Song> found=new ArrayList<>(map.values());h.post(()->{if(dead)return;scanning=false;if(!found.isEmpty()||error.isEmpty()){songs=found;Store.write(this,"library",songs);}if(ctl!=null&&ctl.getMediaItemCount()==0&&!songs.isEmpty())setQueue(songs,0,0,Store.prefs(this).getBoolean("auto",true));if(page.equals("搜尋"))populate();else render();if(status!=null)status.setText((error.isEmpty()?"掃描完成":error)+" · "+songs.size()+" 首");if(user)Toast.makeText(this,"找到 "+songs.size()+" 首音樂",Toast.LENGTH_SHORT).show();});});}
 private static String nonempty(String v,String d){return v==null||v.trim().isEmpty()||v.equals("<unknown>")?d:v;}
 private void walk(Uri tree,String doc,Map<String,Store.Song> map,int depth,Set<String> seen){if(depth>24||map.size()>20000||!seen.add(doc))return;Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(tree,doc);String[] cols={DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE};try(Cursor c=getContentResolver().query(children,cols,null,null,null)){if(c==null)return;while(c.moveToNext()){String id=c.getString(0),name=nonempty(c.getString(1),"未命名歌曲"),mime=nonempty(c.getString(2),"");if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime))walk(tree,id,map,depth+1,seen);else if(mime.startsWith("audio/")||name.toLowerCase(Locale.ROOT).matches(".*\\.(mp3|flac|wav|aac|m4a|ogg|opus|wma|aiff|amr)$")){String u=DocumentsContract.buildDocumentUriUsingTree(tree,id).toString();map.put(u,new Store.Song(u,name,"本機資料夾",""));}}}}
 private void chooseFolder(){try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION|Intent.FLAG_GRANT_PREFIX_URI_PERMISSION);startActivityForResult(i,72);}catch(Exception e){Toast.makeText(this,"此車機沒有可用的資料夾選擇器",Toast.LENGTH_LONG).show();}}
 @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==72&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri u=data.getData();try{getContentResolver().takePersistableUriPermission(u,data.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION);Set<String> s=new HashSet<>(Store.prefs(this).getStringSet("trees",Collections.emptySet()));s.add(u.toString());Store.prefs(this).edit().putStringSet("trees",s).apply();scan(true);}catch(Exception e){Toast.makeText(this,"未取得持續讀取權限",Toast.LENGTH_LONG).show();}}}
 private int dp(float x){return Math.round(x*getResources().getDisplayMetrics().density);}
 private void theme(){String t=Store.prefs(this).getString("theme","黑金");if(t.equals("米白")){bg=0xffF4F1EA;panel=0xffE5DFD2;fg=0xff25272B;muted=0xff565A61;gold=0xff795923;}else if(t.equals("深藍")){bg=0xff0B1424;panel=0xff17283E;fg=0xffF2F6FF;muted=0xffA8BBD4;gold=0xff90CFFF;}else{bg=0xff111316;panel=0xff20242A;fg=0xffF4F0E7;muted=0xffADB2BA;gold=0xffD8B87A;}}
 private GradientDrawable shape(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}
 private LinearLayout col(){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);return x;}
 private LinearLayout row(){LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.HORIZONTAL);x.setGravity(Gravity.CENTER_VERTICAL);return x;}
 private TextView txt(String s,int size,int color,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(color);if(bold)v.setTypeface(null,Typeface.BOLD);return v;}
 private TextView button(String s,Runnable action){TextView v=txt(s,18,fg,true);v.setGravity(Gravity.CENTER);v.setMinHeight(dp(48));v.setPadding(dp(6),dp(4),dp(6),dp(4));v.setBackground(shape(panel,12));v.setOnClickListener(w->action.run());v.setFocusable(true);return v;}
 private void add(LinearLayout p,View v,int w,int height,float weight){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(w<0?w:dp(w),height<0?height:dp(height),weight);lp.setMargins(dp(4),dp(3),dp(4),dp(3));p.addView(v,lp);}
 private void render(){title=artist=time=play=heart=shuffle=repeat=status=null;seek=null;list=null;root=col();root.setPadding(dp(12),dp(6),dp(12),dp(6));root.setBackgroundColor(bg);setContentView(root);if(Build.VERSION.SDK_INT>=35)root.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets in=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(dp(12)+in.left,dp(6)+in.top,dp(12)+in.right,dp(6)+in.bottom);return i;});LinearLayout top=row();add(top,txt("M〰  MOTIF",23,gold,true),-2,-2,0);top.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));status=txt("離線音樂 · 無廣告",13,muted,false);add(top,status,-2,-2,0);add(root,top,-1,-2,0);body=col();add(root,body,-1,0,1);
 if(page.equals("首頁"))home();else if(page.equals("設定"))settings();else library();
 LinearLayout nav=row();for(String label:new String[]{"首頁","音樂庫","搜尋","播放清單","設定"}){TextView v=button(label,()->{page=label;filter="";render();});if(page.equals(label))v.setTextColor(gold);add(nav,v,0,48,1);}add(root,nav,-1,-2,0);refresh();}
 private void home(){LinearLayout main=row();LinearLayout cover=col();cover.setGravity(Gravity.CENTER);GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{panel,bg,gold});d.setCornerRadius(dp(20));cover.setBackground(d);TextView icon=txt("♫",64,fg,true);icon.setGravity(Gravity.CENTER);add(cover,icon,-1,-2,0);TextView badge=txt("M O T I F  /  DRIVE",14,fg,true);badge.setGravity(Gravity.CENTER);add(cover,badge,-1,-2,0);add(main,cover,0,-1,0.85f);
 ScrollView sc=new ScrollView(this);sc.setFillViewport(true);LinearLayout info=col();info.setGravity(Gravity.CENTER_VERTICAL);sc.addView(info);add(info,txt("正在播放",15,gold,true),-1,-2,0);title=txt("尚未選擇音樂",26,fg,true);title.setMaxLines(2);add(info,title,-1,-2,0);artist=txt("先掃描或加入資料夾",17,muted,false);artist.setMaxLines(1);add(info,artist,-1,-2,0);time=txt("00:00 / 00:00",14,muted,false);add(info,time,-1,-2,0);seek=new SeekBar(this);seek.setMax(1000);seek.setProgressTintList(android.content.res.ColorStateList.valueOf(gold));seek.setThumbTintList(android.content.res.ColorStateList.valueOf(gold));seek.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){dragging=true;}public void onProgressChanged(SeekBar b,int p,boolean user){}public void onStopTrackingTouch(SeekBar b){if(ctl!=null&&ctl.getDuration()>0)ctl.seekTo(ctl.getDuration()*b.getProgress()/1000);dragging=false;}});add(info,seek,-1,30,0);
 LinearLayout controls=row();add(controls,button("⏮",()->{if(ctl!=null)ctl.seekToPreviousMediaItem();}),0,52,1);play=button("▶",this::playToggle);play.setTextColor(gold);play.setTextSize(26);add(controls,play,0,52,1.2f);add(controls,button("⏭",()->{if(ctl!=null)ctl.seekToNextMediaItem();}),0,52,1);add(info,controls,-1,-2,0);LinearLayout other=row();heart=button("♡",()->{if(ctl!=null&&ctl.getCurrentMediaItem()!=null)Store.favorite(this,ctl.getCurrentMediaItem().mediaId);refresh();});shuffle=button("隨機",()->{if(ctl!=null)ctl.setShuffleModeEnabled(!ctl.getShuffleModeEnabled());});repeat=button("循環",()->{if(ctl!=null)ctl.setRepeatMode((ctl.getRepeatMode()+1)%3);});add(other,heart,0,48,1);add(other,shuffle,0,48,1);add(other,repeat,0,48,1);add(info,other,-1,-2,0);add(main,sc,0,-1,1.3f);add(body,main,-1,0,1);}
 private void library(){LinearLayout tools=row();if(page.equals("音樂庫")){add(tools,button("掃描本機",this::permission),0,48,1);add(tools,button("加入 USB／資料夾",this::chooseFolder),0,48,1);}else if(page.equals("搜尋")){EditText search=new EditText(this);search.setSingleLine();search.setTextColor(fg);search.setHintTextColor(muted);search.setTextSize(20);search.setHint("搜尋歌曲、歌手、專輯（停車時操作）");search.setText(filter);add(tools,search,-1,50,0);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){filter=s.toString();populate();}public void afterTextChanged(Editable e){}});}else{add(tools,button("我的最愛",()->{filter="fav";populate();}),0,48,1);add(tools,button("目前播放清單",()->{filter="queue";populate();}),0,48,1);add(tools,button("全部歌曲",()->{filter="";populate();}),0,48,1);}add(body,tools,-1,-2,0);ScrollView scroll=new ScrollView(this);list=col();scroll.addView(list);add(body,scroll,-1,0,1);populate();LinearLayout mini=row();add(mini,button("⏮",()->{if(ctl!=null)ctl.seekToPreviousMediaItem();}),54,48,0);play=button("▶",this::playToggle);add(mini,play,58,48,0);add(mini,button("⏭",()->{if(ctl!=null)ctl.seekToNextMediaItem();}),54,48,0);title=txt("尚未播放",17,fg,true);title.setMaxLines(1);add(mini,title,0,48,1);add(body,mini,-1,-2,0);}
 private void populate(){if(list==null)return;list.removeAllViews();List<Store.Song> selected=new ArrayList<>();String f=filter.toLowerCase(Locale.ROOT);Set<String> fav=Store.favorites(this);List<Store.Song> src=page.equals("播放清單")&&filter.equals("queue")&&ctl!=null?Store.queue(ctl):songs;for(Store.Song s:src){if(page.equals("播放清單")&&filter.equals("fav")&&!fav.contains(s.uri))continue;if(page.equals("搜尋")&&!(s.title+" "+s.artist+" "+s.album).toLowerCase(Locale.ROOT).contains(f))continue;selected.add(s);}if(selected.isEmpty()){add(list,txt("沒有歌曲。請至音樂庫掃描本機或加入資料夾。",18,muted,false),-1,-2,0);return;}for(int i=0;i<selected.size();i++){Store.Song s=selected.get(i);final int n=i;LinearLayout r=row();r.setBackground(shape(panel,10));TextView name=txt(s.title+"  ·  "+s.artist,17,fg,false);name.setSingleLine(true);name.setEllipsize(TextUtils.TruncateAt.END);name.setGravity(Gravity.CENTER_VERTICAL);name.setOnClickListener(v->{setQueue(selected,n,0,true);page="首頁";render();});add(r,name,0,52,1);add(r,button(fav.contains(s.uri)?"♥":"♡",()->{Store.favorite(this,s.uri);populate();}),54,48,0);add(r,button("▶",()->{setQueue(selected,n,0,true);page="首頁";render();}),54,48,0);add(list,r,-1,-2,0);}}
 private void settings(){ScrollView scroll=new ScrollView(this);LinearLayout content=col();scroll.addView(content);Switch auto=new Switch(this);auto.setText("啟動後自動播放（首次需授權音樂）");auto.setTextSize(19);auto.setTextColor(fg);auto.setChecked(Store.prefs(this).getBoolean("auto",true));auto.setOnCheckedChangeListener((b,v)->Store.prefs(this).edit().putBoolean("auto",v).apply());add(content,auto,-1,54,0);add(content,txt("介面主題",18,muted,true),-1,-2,0);LinearLayout themes=row();for(String t:new String[]{"黑金","深藍","米白"})add(themes,button(t,()->{Store.prefs(this).edit().putString("theme",t).apply();theme();render();}),0,48,1);add(content,themes,-1,-2,0);LinearLayout vol=row();add(vol,txt("音樂音量",18,fg,true),-2,-2,0);android.media.AudioManager am=(android.media.AudioManager)getSystemService(AUDIO_SERVICE);SeekBar volume=new SeekBar(this);volume.setMax(am.getStreamMaxVolume(android.media.AudioManager.STREAM_MUSIC));volume.setProgress(am.getStreamVolume(android.media.AudioManager.STREAM_MUSIC));volume.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int p,boolean user){if(user)try{am.setStreamVolume(android.media.AudioManager.STREAM_MUSIC,p,0);}catch(Exception ignored){}}});add(vol,volume,0,48,1);add(content,vol,-1,-2,0);add(content,txt("MOTIF 0.1.0 · 本機音樂播放器\n開機自啟由安卓盒設定；方向盤控制取決於盒子是否傳送媒體按鍵。請停車後管理歌曲及設定。",15,muted,false),-1,-2,0);add(body,scroll,-1,0,1);}
 private void refresh(){if(ctl==null)return;MediaItem m=ctl.getCurrentMediaItem();if(title!=null)title.setText(m==null?"尚未選擇音樂":Store.str(ctl.getMediaMetadata().title));if(artist!=null)artist.setText(m==null?"先掃描或加入資料夾":Store.str(ctl.getMediaMetadata().artist));if(play!=null)play.setText(ctl.getPlayWhenReady()?"Ⅱ":"▶");if(heart!=null)heart.setText(m!=null&&Store.favorites(this).contains(m.mediaId)?"♥":"♡");if(shuffle!=null)shuffle.setTextColor(ctl.getShuffleModeEnabled()?gold:muted);if(repeat!=null){repeat.setText(ctl.getRepeatMode()==1?"單曲循環":ctl.getRepeatMode()==2?"清單循環":"不循環");repeat.setTextColor(ctl.getRepeatMode()==0?muted:gold);}long duration=ctl.getDuration(),pos=ctl.getCurrentPosition();if(time!=null)time.setText(fmt(pos)+" / "+fmt(duration));if(seek!=null&&!dragging)seek.setProgress(duration>0?(int)Math.min(1000,pos*1000/duration):0);}
 private String fmt(long x){long sec=Math.max(0,x)/1000;return String.format(Locale.ROOT,"%02d:%02d",sec/60,sec%60);}
 @Override protected void onDestroy(){dead=true;h.removeCallbacksAndMessages(null);io.shutdownNow();if(pending!=null)MediaController.releaseFuture(pending);super.onDestroy();}
}
